package run.ikaros.password; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Mono; import run.ikaros.common.NotFoundException; @Service public class PasswordExportService{private final PasswordVaultRepository vaults;private final PasswordVaultItemRepository items;public PasswordExportService(PasswordVaultRepository v,PasswordVaultItemRepository i){vaults=v;items=i;}public Mono<EncryptedVaultExport> export(UUID a,UUID id){return own(a,id).flatMap(v->items.findAllByVaultIdAndOwnerIdAndUpdatedAtGreaterThanOrderByUpdatedAtAsc(id,a,Instant.EPOCH).collectList().map(xs->new EncryptedVaultExport(v.id(),v.securityProfile(),v.cryptoContext(),xs.stream().map(i->new PasswordVaultItemView(i.id(),i.vaultId(),i.itemType(),i.encryptedName(),i.encryptedPayload(),i.encryptedCustomFields(),i.favorite(),i.revision(),i.tombstone(),i.createdAt(),i.updatedAt())).toList())));}private Mono<PasswordVaultEntity> own(UUID a,UUID id){return vaults.findById(id).filter(v->v.ownerId().equals(a)).switchIfEmpty(Mono.error(new NotFoundException("Password Vault 不存在或无权访问")));}}
